const path = require('path');
const ROOT = '/srv/documents';

// Case 1: plain traversal (no encoding) - query parser passes .. through
console.log('plain .. :', path.join(ROOT, '../../etc/passwd'));

// Case 2: single decode already done by query parser, decodeURIComponent is no-op here
console.log('decoded once:', path.join(ROOT, decodeURIComponent('../../etc/passwd')));

// Case 3: double-decode - attacker sends %252F to survive one decode
const queryParserDecoded = '..%2F..%2Fetc%2Fpasswd'; // what req.query.name holds after Express decodes %25->%
console.log('double decode:', path.join(ROOT, decodeURIComponent(queryParserDecoded)));

// Show that no containment check exists: result escapes ROOT
const result = path.join(ROOT, '../../etc/passwd');
console.log('startsWith ROOT?', result.startsWith(ROOT), '=>', result);
"
"}

