const path = require('path');
const ROOT = '/srv/documents';
// Demonstrate canonicalization behavior: path.join resolves .. but does NOT contain within ROOT
const inputs = ['..%2F..%2Fetc%2Fpasswd', '%2e%2e%2f%2e%2e%2fetc%2fpasswd', 'legit.txt', 'sub/legit.txt'];
for (const i of inputs) {
  let name;
  try { name = decodeURIComponent(i); } catch(e){ name='<err>'; }
  const joined = path.join(ROOT, name);
  const resolved = path.resolve(ROOT, name);
  console.log(JSON.stringify(i), '-> name=',JSON.stringify(name),
    '| joined=',joined,'| resolved=',resolved,
    '| contained?', (resolved===ROOT||resolved.startsWith(ROOT+path.sep)));
}
""}

